  1→import { test, expect, Browser } from '@playwright/test';
  2→import {
  3→  createWalletTestAccount,
  4→  closeWalletTestAccounts,
  5→  navigateToShared,
  6→  navigateToFiles,
  7→  type WalletTestAccount,
  8→} from '../utils/multi-account-wallet';
  9→import { createTestTextFile, createTestImageFile, cleanupTestFiles } from '../utils/test-files';
 10→import { FileListPage } from '../page-objects/file-browser/file-list.page';
 11→import { UploadZonePage } from '../page-objects/file-browser/upload-zone.page';
 12→import { ContextMenuPage } from '../page-objects/file-browser/context-menu.page';
 13→import { CreateFolderDialogPage } from '../page-objects/dialogs/create-folder-dialog.page';
 14→import { ShareDialogPage } from '../page-objects/dialogs/share-dialog.page';
 15→import { SharedFileBrowserPage } from '../page-objects/file-browser/shared-file-browser.page';
 16→
 17→/**
 18→ * Sharing Workflow E2E Test Suite
 19→ *
 20→ * Tests user-to-user sharing with multiple authenticated accounts.
 21→ * Each test account gets its own browser context (isolated cookies/storage).
 22→ *
 23→ * Accounts:
 24→ * - Alice: primary sharer (creates content and shares it)
 25→ * - Bob: primary recipient (receives and browses shared content)
 26→ * - Charlie: secondary recipient (for multi-recipient tests)
 27→ *
 28→ * Test flow:
 29→ * 1. Setup: Create 3 accounts, Alice creates test content
 30→ * 2. Basic sharing: Alice shares file with Bob, Bob receives it
 31→ * 3. Folder sharing: Alice shares folder tree, Bob navigates it
 32→ * 4. Multi-recipient: Alice adds Charlie to existing share
 33→ * 5. Revocation: Alice revokes Bob's access
 34→ * 6. Post-share mutations: Alice adds files to shared folder
 35→ * 7. Error cases: Invalid key, self-share, user not found
 36→ * 8. Hide share: Bob hides a shared item
 37→ */
 38→test.describe.serial('Sharing Workflow', () => {
 39→  let browser: Browser;
 40→  let alice: WalletTestAccount;
 41→  let bob: WalletTestAccount;
 42→  let charlie: WalletTestAccount;
 43→
 44→  // Page objects per account
 45→  let aliceFileList: FileListPage;
 46→  let aliceUploadZone: UploadZonePage;
 47→  let aliceContextMenu: ContextMenuPage;
 48→  let aliceCreateFolderDialog: CreateFolderDialogPage;
 49→  let aliceShareDialog: ShareDialogPage;
 50→
 51→  let bobSharedBrowser: SharedFileBrowserPage;
 52→  let bobContextMenu: ContextMenuPage;
 53→
 54→  let charlieSharedBrowser: SharedFileBrowserPage;
 55→
 56→  // Test data - unique per run
 57→  const runId = Date.now().toString();
 58→
 59→  // Shared file
 60→  const sharedFileName = `shared-file-${runId}.txt`;
 61→  const sharedFileContent = 'This file is shared with Bob';
 62→
 63→  // Shared folder structure
 64→  const sharedFolderName = `shared-folder-${runId}`;
 65→  const subFolderName = `subfolder-${runId}`;
 66→  const folderFile1Name = `folder-file1-${runId}.txt`;
 67→  const folderFile2Name = `subfolder-file-${runId}.txt`;
 68→
 69→  // Post-share file (added after share is created)
 70→  const postShareFileName = `added-after-share-${runId}.txt`;
 71→  const postShareFileContent = 'This file was added after the share was created';
 72→
 73→  // Preview test files (image in shared folder)
 74→  const sharedImageName = `test-image-${runId}.png`;
 75→
 76→  // Helper to truncate a public key for matching in the UI
 77→  function truncateKey(key: string): string {
 78→    const hex = key.startsWith('0x') ? key.slice(2) : key;
 79→    return `0x${hex.slice(0, 4)}...${hex.slice(-4)}`;
 80→  }
 81→
 82→  // ============================================
 83→  // Alice helpers
 84→  // ============================================
 85→
 86→  async function aliceCreateFolder(name: string): Promise<void> {
 87→    const newFolderButton = alice.page.locator('.file-browser-new-folder-button');
 88→    await newFolderButton.click();
 89→    await aliceCreateFolderDialog.waitForOpen();
 90→    await aliceCreateFolderDialog.createFolder(name);
 91→    await aliceFileList.waitForItemToAppear(name, { timeout: 30000 });
 92→  }
 93→
 94→  async function aliceUploadFile(fileName: string, content: string): Promise<void> {
 95→    const testFile = createTestTextFile(fileName, content);
 96→    await aliceUploadZone.uploadFile(testFile.path);
 97→
 98→    // Wait for upload: check for either the file appearing or an error alert
 99→    await Promise.race([
100→      aliceFileList.waitForItemToAppear(fileName, { timeout: 30000 }),
101→      alice.page
102→        .locator('[role="alert"]')
103→        .waitFor({ state: 'visible', timeout: 30000 })
104→        .then(async () => {
105→          const alertText = await alice.page.locator('[role="alert"]').textContent();
106→          throw new Error(`Upload failed with alert: ${alertText}`);
107→        }),
108→    ]);
109→  }
110→
111→  async function aliceNavigateIntoFolder(name: string): Promise<void> {
112→    await aliceFileList.doubleClickFolder(name);
113→    // Wait for breadcrumbs to show the folder name
114→    await alice.page.locator('.breadcrumb-item', { hasText: name.toLowerCase() }).waitFor({
115→      state: 'visible',
116→      timeout: 30000,
117→    });
118→  }
119→
120→  async function aliceNavigateBack(): Promise<void> {
121→    await alice.page.locator('[data-testid="parent-dir-row"]').dblclick();
122→    await alice.page.waitForTimeout(500);
123→  }
124→
125→  async function aliceOpenShareDialog(itemName: string): Promise<void> {
126→    await aliceFileList.rightClickItem(itemName);
127→    await aliceContextMenu.waitForOpen();
128→    await aliceContextMenu.clickShare();
129→    await aliceShareDialog.waitForOpen();
130→    await aliceShareDialog.waitForRecipientsLoaded();
131→  }
132→
133→  // ============================================
134→  // Setup and Teardown
135→  // ============================================
136→
137→  test.beforeAll(async ({ browser: testBrowser }) => {
138→    browser = testBrowser;
139→  });
140→
141→  test.afterAll(async () => {
142→    cleanupTestFiles();
143→    if (alice || bob || charlie) {
144→      await closeWalletTestAccounts([alice, bob, charlie].filter(Boolean));
145→    }
146→  });
147→
148→  // ============================================
149→  // Phase 1: Account Setup
150→  // ============================================
151→
152→  test('1.1 Create test accounts (Alice, Bob, Charlie)', async () => {
153→    test.setTimeout(300_000); // 3 sequential wallet logins (up to 90s each) + vault init
154→    // Create accounts sequentially (each needs its own context + wallet login)
155→    alice = await createWalletTestAccount(browser, 'alice');
156→    bob = await createWalletTestAccount(browser, 'bob');
157→    charlie = await createWalletTestAccount(browser, 'charlie');
158→
159→    // Initialize page objects for Alice
160→    aliceFileList = new FileListPage(alice.page);
161→    aliceUploadZone = new UploadZonePage(alice.page);
162→    aliceContextMenu = new ContextMenuPage(alice.page);
163→    aliceCreateFolderDialog = new CreateFolderDialogPage(alice.page);
164→    aliceShareDialog = new ShareDialogPage(alice.page);
165→
166→    // Initialize page objects for Bob
167→    bobSharedBrowser = new SharedFileBrowserPage(bob.page);
168→    bobContextMenu = new ContextMenuPage(bob.page);
169→
170→    // Initialize page objects for Charlie
171→    charlieSharedBrowser = new SharedFileBrowserPage(charlie.page);
172→
173→    // Verify all three accounts have different public keys
174→    expect(alice.publicKey).not.toBe(bob.publicKey);
175→    expect(alice.publicKey).not.toBe(charlie.publicKey);
176→    expect(bob.publicKey).not.toBe(charlie.publicKey);
177→  });
178→
179→  // ============================================
180→  // Phase 2: Alice Creates Content
181→  // ============================================
182→
183→  test('2.1 Alice creates a test file at root', async () => {
184→    await aliceUploadFile(sharedFileName, sharedFileContent);
185→    expect(await aliceFileList.isItemVisible(sharedFileName)).toBe(true);
186→  });
187→
188→  test('2.2 Alice creates a folder with nested content', async () => {
189→    // Create top-level folder
190→    await aliceCreateFolder(sharedFolderName);
191→    expect(await aliceFileList.isItemVisible(sharedFolderName)).toBe(true);
192→
193→    // Navigate into it and add a file + an image
194→    await aliceNavigateIntoFolder(sharedFolderName);
195→    await aliceUploadFile(folderFile1Name, 'File inside shared folder');
196→
197→    // Upload a PNG image (needed for shared preview test in Phase 11)
198→    const testImage = createTestImageFile(sharedImageName);
199→    await aliceUploadZone.uploadFile(testImage.path);
200→    await aliceFileList.waitForItemToAppear(sharedImageName, { timeout: 30000 });
201→
202→    // Create subfolder
203→    await aliceCreateFolder(subFolderName);
204→
205→    // Navigate into subfolder and add a file
206→    await aliceNavigateIntoFolder(subFolderName);
207→    await aliceUploadFile(folderFile2Name, 'File inside subfolder');
208→
209→    // Navigate back to root
210→    await aliceNavigateBack(); // back to shared folder
211→    await aliceNavigateBack(); // back to root
212→  });
213→
214→  // ============================================
215→  // Phase 3: Basic File Sharing
216→  // ============================================
217→
218→  test('3.1 Alice shares a file with Bob', async () => {
219→    await aliceOpenShareDialog(sharedFileName);
220→
221→    // Should start with no recipients
222→    expect(await aliceShareDialog.getRecipientCount()).toBe(0);
223→
224→    // Share with Bob
225→    await aliceShareDialog.shareWithKey(bob.publicKey);
226→    const successText = await aliceShareDialog.waitForSuccess({ timeout: 30000 });
227→    expect(successText).toContain(truncateKey(bob.publicKey));
228→
229→    // Verify recipient appears in the list
230→    expect(await aliceShareDialog.getRecipientCount()).toBe(1);
231→    const recipientKeys = await aliceShareDialog.getRecipientKeys();
232→    expect(recipientKeys[0]).toBe(truncateKey(bob.publicKey));
233→
234→    await aliceShareDialog.close();
235→  });
236→
237→  test('3.2 Bob sees the shared file in ~/shared', async () => {
238→    await navigateToShared(bob);
239→
240→    // Wait for the shared items to load
241→    await bobSharedBrowser.waitForLoaded({ timeout: 30000 });
242→
243→    // Bob should see Alice's shared file
244→    await bobSharedBrowser.waitForSharedItem(sharedFileName, { timeout: 15000 });
245→    expect(await bobSharedBrowser.getSharedItemCount()).toBeGreaterThanOrEqual(1);
246→
247→    // Verify [RO] badge
248→    const roBadge = bobSharedBrowser.getReadOnlyBadge(sharedFileName);
249→    expect(await roBadge.isVisible()).toBe(true);
250→
251→    // Verify "SHARED BY" shows Alice's truncated key
252→    const sharedBy = await bobSharedBrowser.getSharedBy(sharedFileName);
253→    expect(sharedBy).toContain(truncateKey(alice.publicKey));
254→  });
255→
256→  // ============================================
257→  // Phase 4: Folder Sharing with Descendants
258→  // ============================================
259→
260→  test('4.1 Alice shares a folder with Bob', async () => {
261→    // Make sure Alice is on files page
262→    await navigateToFiles(alice);
263→    await aliceFileList.waitForItemToAppear(sharedFolderName, { timeout: 15000 });
264→
265→    await aliceOpenShareDialog(sharedFolderName);
266→
267→    // Share with Bob - folder sharing re-wraps descendant keys
268→    await aliceShareDialog.shareWithKey(bob.publicKey);
269→
270→    // Wait for progress (folder sharing re-wraps keys for each child)
271→    // The progress may be very fast for small folders, so we just wait for success
272→    const successText = await aliceShareDialog.waitForSuccess({ timeout: 60000 });
273→    expect(successText).toContain(truncateKey(bob.publicKey));
274→
275→    await aliceShareDialog.close();
276→  });
277→
278→  test('4.2 Bob navigates the shared folder tree', async () => {
279→    // Navigate to Bob's shared view
280→    await navigateToShared(bob);
281→    await bobSharedBrowser.waitForLoaded({ timeout: 30000 });
282→
283→    // Find and open the shared folder
284→    await bobSharedBrowser.waitForSharedItem(sharedFolderName, { timeout: 15000 });
285→
286→    // Click the shared item and wait — IPNS resolution can be slow on first access
287→    await bobSharedBrowser.openSharedItem(sharedFolderName);
288→    await bob.page.waitForTimeout(3000);
289→
290→    // If IPNS resolution failed on first try, retry once
291→    const parentDirVisible = await bobSharedBrowser.parentDirRow().isVisible();
292→    if (!parentDirVisible) {
293→      await navigateToShared(bob);
294→      await bobSharedBrowser.waitForLoaded({ timeout: 30000 });
295→      await bobSharedBrowser.waitForSharedItem(sharedFolderName, { timeout: 15000 });
296→      await bobSharedBrowser.navigateIntoFolder(sharedFolderName);
297→    }
298→
299→    // Should see folder contents: the file and subfolder
300→    const itemNames = await bobSharedBrowser.getFolderItemNames();
301→    expect(itemNames.some((n) => n.includes(folderFile1Name))).toBe(true);
302→    expect(itemNames.some((n) => n.includes(subFolderName))).toBe(true);
303→
304→    // Navigate into subfolder
305→    await bobSharedBrowser.doubleClickFolderItem(subFolderName);
306→    // Wait for subfolder content to load
307→    await bob.page.waitForTimeout(2000);
308→
309→    const subItems = await bobSharedBrowser.getFolderItemNames();
310→    expect(subItems.some((n) => n.includes(folderFile2Name))).toBe(true);
311→
312→    // Navigate back to shared root
313→    await bobSharedBrowser.navigateToRoot();
314→    await bobSharedBrowser.waitForLoaded({ timeout: 15000 });
315→  });
316→
317→  // ============================================
318→  // Phase 5: Multi-Recipient (Add Charlie)
319→  // ============================================
320→
321→  test('5.1 Alice adds Charlie as a second recipient', async () => {
322→    await navigateToFiles(alice);
323→    await aliceFileList.waitForItemToAppear(sharedFolderName, { timeout: 15000 });
324→
325→    await aliceOpenShareDialog(sharedFolderName);
326→
327→    // Bob should already be a recipient
328→    await aliceShareDialog.waitForRecipientsLoaded();
329→    expect(await aliceShareDialog.getRecipientCount()).toBe(1);
330→
331→    // Add Charlie
332→    await aliceShareDialog.shareWithKey(charlie.publicKey);
333→    const successText = await aliceShareDialog.waitForSuccess({ timeout: 60000 });
334→    expect(successText).toContain(truncateKey(charlie.publicKey));
335→
336→    // Now should have 2 recipients
337→    expect(await aliceShareDialog.getRecipientCount()).toBe(2);
338→
339→    await aliceShareDialog.close();
340→  });
341→
342→  test('5.2 Charlie sees the shared folder', async () => {
343→    await navigateToShared(charlie);
344→    await charlieSharedBrowser.waitForLoaded({ timeout: 30000 });
345→
346→    await charlieSharedBrowser.waitForSharedItem(sharedFolderName, { timeout: 15000 });
347→    expect(await charlieSharedBrowser.getSharedItemCount()).toBeGreaterThanOrEqual(1);
348→  });
349→
350→  // ============================================
351→  // Phase 6: Revoke Access
352→  // ============================================
353→
354→  test("6.1 Alice revokes Bob's access to the shared folder", async () => {
355→    await navigateToFiles(alice);
356→    await aliceFileList.waitForItemToAppear(sharedFolderName, { timeout: 15000 });
357→
358→    await aliceOpenShareDialog(sharedFolderName);
359→    await aliceShareDialog.waitForRecipientsLoaded();
360→
361→    // Should have 2 recipients (Bob + Charlie)
362→    expect(await aliceShareDialog.getRecipientCount()).toBe(2);
363→
364→    // Revoke Bob
365→    const bobTruncated = truncateKey(bob.publicKey);
366→    await aliceShareDialog.revokeRecipient(bobTruncated);
367→
368→    // Should now have 1 recipient (Charlie only)
369→    expect(await aliceShareDialog.getRecipientCount()).toBe(1);
370→
371→    await aliceShareDialog.close();
372→  });
373→
374→  test('6.2 Bob no longer sees the shared folder', async () => {
375→    // Reload Bob's shared view to get fresh data
376→    await navigateToShared(bob);
377→    await bobSharedBrowser.waitForLoaded({ timeout: 30000 });
378→
379→    // The shared folder should no longer appear for Bob
380→    // (may still show the shared file from test 3.1)
381→    const itemNames = await bobSharedBrowser.getSharedItemNames();
382→    const hasFolderShare = itemNames.some((n) => n.includes(sharedFolderName));
383→    expect(hasFolderShare).toBe(false);
384→  });
385→
386→  test('6.3 Charlie still has access', async () => {
387→    await navigateToShared(charlie);
388→    await charlieSharedBrowser.waitForLoaded({ timeout: 30000 });
389→
390→    await charlieSharedBrowser.waitForSharedItem(sharedFolderName, { timeout: 15000 });
391→    expect(await charlieSharedBrowser.getSharedItemCount()).toBeGreaterThanOrEqual(1);
392→  });
393→
394→  // ============================================
395→  // Phase 7: Post-Share Mutations
396→  // ============================================
397→
398→  test('7.1 Alice adds a file to the shared folder after sharing', async () => {
399→    await navigateToFiles(alice);
400→    await aliceFileList.waitForItemToAppear(sharedFolderName, { timeout: 15000 });
401→
402→    // Navigate into the shared folder
403→    await aliceNavigateIntoFolder(sharedFolderName);
404→
405→    // Upload a new file
406→    await aliceUploadFile(postShareFileName, postShareFileContent);
407→    expect(await aliceFileList.isItemVisible(postShareFileName)).toBe(true);
408→
409→    // Navigate back
410→    await aliceNavigateBack();
411→  });
412→
413→  test('7.2 Charlie sees the newly added file', async () => {
414→    // IPNS propagation on staging can take many seconds after Alice's
415→    // upload in 7.1. Retry navigation into the shared folder to trigger
416→    // fresh IPNS resolves until the post-share file appears.
417→    test.setTimeout(120000);
418→    await charlie.page.waitForTimeout(3000);
419→
420→    const maxAttempts = 3;
421→    let found = false;
422→
423→    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
424→      // Navigate Charlie into the shared folder
425→      await navigateToShared(charlie);
426→      await charlieSharedBrowser.waitForLoaded({ timeout: 30000 });
427→      await charlieSharedBrowser.navigateIntoFolder(sharedFolderName);
428→
429→      // Wait for the post-share file to appear
430→      try {
431→        await charlieSharedBrowser
432→          .getFolderItem(postShareFileName)
433→          .waitFor({ state: 'visible', timeout: 30000 });
434→        found = true;
435→        break;
436→      } catch {
437→        // IPNS hasn't propagated yet — navigate back and retry
438→        if (attempt < maxAttempts) {
439→          await charlieSharedBrowser.navigateToRoot();
440→          await charlie.page.waitForTimeout(5000);
441→        }
442→      }
443→    }
444→
445→    expect(found).toBe(true);
446→    await charlieSharedBrowser.navigateToRoot();
447→  });
448→
449→  test('7.3 Charlie can preview the post-share file (re-wrapping verification)', async () => {
450→    // This test verifies the re-wrapping fix: files uploaded AFTER sharing
451→    // must have their keys re-wrapped for recipients. Without the fix,
452→    // Charlie would see "No re-wrapped file key available" error.
453→    await navigateToShared(charlie);
454→    await charlieSharedBrowser.waitForLoaded({ timeout: 30000 });
455→    await charlieSharedBrowser.navigateIntoFolder(sharedFolderName);
456→
457→    // Wait for the post-share file to be visible
458→    await charlieSharedBrowser
459→      .getFolderItem(postShareFileName)
460→      .waitFor({ state: 'visible', timeout: 15000 });
461→
462→    // Right-click and open the text file via Edit (opens read-only for shared files)
463→    await charlieSharedBrowser.rightClickFolderItem(postShareFileName);
464→    const charlieContextMenu = new ContextMenuPage(charlie.page);
465→    await charlieContextMenu.waitForOpen();
466→    await charlieContextMenu.clickEdit();
467→
468→    // The text editor dialog should open in read-only mode
469→    const editorDialog = charlie.page.locator('.text-editor-modal');
470→    await editorDialog.waitFor({ state: 'visible', timeout: 30000 });
471→
472→    // Verify the content loaded (not an error message).
473→    // The textarea appears immediately but content loads async (IPFS download + decrypt).
474→    // Wait for the textarea to contain the expected text, not just be visible.
475→    const textarea = charlie.page.locator('.text-editor-textarea');
476→    await textarea.waitFor({ state: 'visible', timeout: 15000 });
477→    await expect(textarea).toHaveValue(/added after the share/, { timeout: 15000 });
478→
479→    // Close the dialog
480→    await charlie.page.locator('.text-editor-modal .modal-close').click();
481→    await editorDialog.waitFor({ state: 'hidden' });
482→
483→    await charlieSharedBrowser.navigateToRoot();
484→  });
485→
486→  // ============================================
487→  // Phase 8: Error Cases
488→  // ============================================
489→
490→  test('8.1 Invalid public key format shows error', async () => {
491→    await navigateToFiles(alice);
492→    await aliceFileList.waitForItemToAppear(sharedFileName, { timeout: 15000 });
493→
494→    await aliceOpenShareDialog(sharedFileName);
495→
496→    // Try an invalid key
497→    await aliceShareDialog.shareWithKey('0x1234invalid');
498→    const errorText = await aliceShareDialog.waitForError();
499→    expect(errorText).toContain('invalid key format');
500→
501→    await aliceShareDialog.close();
502→  });
503→
504→  test('8.2 Self-sharing shows error', async () => {
505→    await aliceOpenShareDialog(sharedFileName);
506→
507→    // Try sharing with own key
508→    await aliceShareDialog.shareWithKey(alice.publicKey);
509→    const errorText = await aliceShareDialog.waitForError();
510→    expect(errorText).toContain('cannot share with yourself');
511→
512→    await aliceShareDialog.close();
513→  });
514→
515→  test('8.3 Unregistered user shows error', async () => {
516→    await aliceOpenShareDialog(sharedFileName);
517→
518→    // Use a valid-format key that doesn't belong to any user
519→    // 0x04 + 128 hex chars (65 bytes uncompressed secp256k1)
520→    const fakeKey =
521→      '0x04' +
522→      'aa'.repeat(32) + // x coordinate
523→      'bb'.repeat(32); // y coordinate
524→
525→    await aliceShareDialog.shareWithKey(fakeKey);
526→    const errorText = await aliceShareDialog.waitForError({ timeout: 15000 });
527→    expect(errorText).toContain('user not found');
528→
529→    await aliceShareDialog.close();
530→  });
531→
532→  // ============================================
533→  // Phase 9: Hide Share
534→  // ============================================
535→
536→  test('9.1 Bob hides the shared file', async () => {
537→    await navigateToShared(bob);
538→    await bobSharedBrowser.waitForLoaded({ timeout: 30000 });
539→
540→    // Bob should still see the shared file from test 3.1
541→    await bobSharedBrowser.waitForSharedItem(sharedFileName, { timeout: 15000 });
542→
543→    // Right-click and hide
544→    await bobSharedBrowser.rightClickSharedItem(sharedFileName);
545→    await bobContextMenu.waitForOpen();
546→    await bobContextMenu.clickHide();
547→
548→    // Wait for the item to disappear
549→    await bobSharedBrowser.waitForSharedItemGone(sharedFileName, { timeout: 10000 });
550→  });
551→
552→  // ============================================
553→  // Phase 10: Re-share After Revoke
554→  // ============================================
555→
556→  test('10.1 Alice re-shares the folder with Bob after previous revoke', async () => {
557→    await navigateToFiles(alice);
558→    await aliceFileList.waitForItemToAppear(sharedFolderName, { timeout: 15000 });
559→
560→    await aliceOpenShareDialog(sharedFolderName);
561→
562→    // Charlie should be the only recipient (Bob was revoked in 6.1)
563→    await aliceShareDialog.waitForRecipientsLoaded();
564→    expect(await aliceShareDialog.getRecipientCount()).toBe(1);
565→
566→    // Re-share with Bob
567→    await aliceShareDialog.shareWithKey(bob.publicKey);
568→    const successText = await aliceShareDialog.waitForSuccess({ timeout: 60000 });
569→    expect(successText).toContain(truncateKey(bob.publicKey));
570→
571→    // Now should have 2 recipients again
572→    expect(await aliceShareDialog.getRecipientCount()).toBe(2);
573→
574→    await aliceShareDialog.close();
