  2→
  3→/**
  4→ * Page object for UploadZone component interactions.
  5→ *
  6→ * Encapsulates file upload functionality via both:
  7→ * - Click to upload (file input)
  8→ * - Drag and drop (not reliable in tests, use setInputFiles instead)
  9→ */
 10→export class UploadZonePage {
 11→  constructor(private readonly page: Page) {}
 12→
 13→  /**
 14→   * Get the upload zone dropzone area.
 15→   */
 16→  dropzone(): Locator {
 17→    return this.page.locator('.upload-zone');
 18→  }
 19→
 20→  /**
 21→   * Get the hidden file input element (used by react-dropzone).
 22→   * Checks both the upload zone and the empty state dropzone.
 23→   * Uses first() as there may be multiple upload zones on the page.
 24→   */
 25→  private fileInput(): Locator {
 26→    return this.page
 27→      .locator('.upload-zone input[type="file"], .empty-state input[type="file"]')
 28→      .first();
 29→  }
 30→
 31→  /**
 32→   * Get the upload zone error message if displayed.
 33→   */
 34→  errorMessage(): Locator {
 35→    return this.page.locator('.upload-zone-error');
 36→  }
 37→
 38→  /**
 39→   * Upload a single file via the file input.
 40→   * This is the most reliable method for Playwright tests.
 41→   *
 42→   * @param filePath - Absolute or relative path to the file
 43→   */
 44→  async uploadFile(filePath: string): Promise<void> {
 45→    // Clear previous selection so re-uploading the same file path triggers change
 46→    await this.fileInput().evaluate((el: HTMLInputElement) => {
 47→      el.value = '';
 48→    });
 49→    await this.fileInput().setInputFiles(filePath);
 50→  }
 51→
 52→  /**
 53→   * Upload multiple files via the file input.
 54→   *
 55→   * @param filePaths - Array of file paths
 56→   */
 57→  async uploadFiles(filePaths: string[]): Promise<void> {
 58→    // Clear previous selection so re-uploading the same file paths triggers change
 59→    await this.fileInput().evaluate((el: HTMLInputElement) => {
 60→      el.value = '';
 61→    });
 62→    await this.fileInput().setInputFiles(filePaths);
 63→  }
 64→
 65→  /**
 66→   * Click the dropzone to trigger the file picker dialog.
 67→   * Note: This won't open an actual dialog in headless tests.
 68→   * Use uploadFile() or uploadFiles() instead for actual file upload.
 69→   */
 70→  async clickToUpload(): Promise<void> {
 71→    await this.dropzone().click();
 72→  }
 73→
 74→  /**
 75→   * Check if the dropzone is in uploading state.
 76→   */
 77→  async isUploading(): Promise<boolean> {
 78→    const className = await this.dropzone().getAttribute('class');
 79→    return className?.includes('upload-zone-uploading') ?? false;
 80→  }
 81→
 82→  /**
 83→   * Check if an error message is displayed.
 84→   */
 85→  async hasError(): Promise<boolean> {
 86→    return await this.errorMessage().isVisible();
 87→  }
 88→
 89→  /**
 90→   * Get the error message text if displayed.
 91→   */
 92→  async getErrorText(): Promise<string | null> {
 93→    const isVisible = await this.hasError();
 94→    if (!isVisible) {
 95→      return null;
 96→    }
 97→    return await this.errorMessage().textContent();
 98→  }
 99→
100→  /**
101→   * Dismiss the error message by clicking the dismiss button.
102→   */
103→  async dismissError(): Promise<void> {
104→    await this.errorMessage().locator('.upload-zone-error-dismiss').click();
105→  }
106→
107→  /**
108→   * Wait for upload to complete.
109→   * Waits for the uploading state to clear.
110→   */
111→  async waitForUploadComplete(options?: { timeout?: number }): Promise<void> {
112→    await this.page.waitForFunction(() => {
113→      const zone = document.querySelector('.upload-zone');
114→      return zone && !zone.classList.contains('upload-zone-uploading');
115→    }, options);
116→  }
117→
118→  /**
119→   * Get the upload zone text.
120→   * Returns "Uploading...", "Drop files here", or "Drag files here or click to upload".
121→   */
122→  async getZoneText(): Promise<string> {
123→    return (await this.dropzone().locator('.upload-zone-text').textContent()) ?? '';
124→  }
125→
126→  /**
127→   * Simulate drag-drop file upload.
128→   * Note: This is more complex and less reliable than setInputFiles.
129→   * Prefer uploadFile() for tests.
130→   *
131→   * @param filePath - Path to file to upload
132→   */
133→  async dragDropFile(filePath: string): Promise<void> {
134→    // For Playwright, we can't truly simulate drag-drop from OS.
135→    // Instead, we'll use the file input method which is more reliable.
136→    // This method exists for API compatibility but delegates to uploadFile.
137→    await this.uploadFile(filePath);
138→  }
139→}
