 38→      padRight('Count', 8) +
 39→      padRight('Errors', 8) +
 40→      padRight('p50', 10) +
 41→      padRight('p95', 10) +
 42→      padRight('p99', 10) +
 43→      padRight('Max', 10)
 44→  );
 45→  console.log('─'.repeat(80));
