import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';

describe('Performance instrumentation', () => {
  let originalNodeEnv: string | undefined;
  let originalPerfFlag: unknown;

  beforeEach(() => {
    originalNodeEnv = process.env.NODE_ENV;
    originalPerfFlag = (globalThis as any).__CIPHERBOX_PERF__;
    // Clear performance entries between tests
    performance.clearMarks();
    performance.clearMeasures();
  });

  afterEach(() => {
    process.env.NODE_ENV = originalNodeEnv;
    if (originalPerfFlag === undefined) {
      delete (globalThis as any).__CIPHERBOX_PERF__;
    } else {
      (globalThis as any).__CIPHERBOX_PERF__ = originalPerfFlag;
    }
    vi.resetModules();
  });

  describe('withPerf (enabled)', () => {
    it('creates a performance.measure entry with name starting with "cipherbox:" when enabled', async () => {
      process.env.NODE_ENV = 'test';
      const { withPerf } = await import('../perf');

      await withPerf('upload:full', async () => 'result');

      const measures = performance.getEntriesByType('measure');
      const cbMeasures = measures.filter((m) => m.name.startsWith('cipherbox:'));
      expect(cbMeasures.length).toBeGreaterThanOrEqual(1);
      expect(cbMeasures[0].name).toBe('cipherbox:upload:full');
    });

    it('returns the wrapped function return value unchanged', async () => {
      process.env.NODE_ENV = 'test';
      const { withPerf } = await import('../perf');

      const result = await withPerf('test:op', async () => ({ id: 42, data: [1, 2, 3] }));

      expect(result).toEqual({ id: 42, data: [1, 2, 3] });
    });

    it('clears marks after measurement (no mark accumulation)', async () => {
      process.env.NODE_ENV = 'test';
      const { withPerf } = await import('../perf');

      await withPerf('cleanup:test', async () => 'done');

      const startMarks = performance.getEntriesByName('cipherbox:cleanup:test:start');
      const endMarks = performance.getEntriesByName('cipherbox:cleanup:test:end');
      expect(startMarks).toHaveLength(0);
      expect(endMarks).toHaveLength(0);
    });

    it('propagates errors from the wrapped function without swallowing them', async () => {
      process.env.NODE_ENV = 'test';
      const { withPerf } = await import('../perf');

      await expect(
        withPerf('error:test', async () => {
          throw new Error('upload failed');
        })
      ).rejects.toThrow('upload failed');
    });
  });

  describe('withPerf (disabled in production)', () => {
    it('does NOT create marks/measures when NODE_ENV=production and __CIPHERBOX_PERF__ is not set', async () => {
      process.env.NODE_ENV = 'production';
      delete (globalThis as any).__CIPHERBOX_PERF__;
      const { withPerf } = await import('../perf');

      performance.clearMarks();
      performance.clearMeasures();

      const result = await withPerf('prod:test', async () => 'value');

      expect(result).toBe('value');
      const measures = performance.getEntriesByType('measure');
      const cbMeasures = measures.filter((m) => m.name.startsWith('cipherbox:'));
      expect(cbMeasures).toHaveLength(0);
    });
  });

  describe('markStart / markEnd (disabled)', () => {
    it('markStart returns empty string when disabled, markEnd is a no-op when startMark is empty', async () => {
      process.env.NODE_ENV = 'production';
      delete (globalThis as any).__CIPHERBOX_PERF__;
      const { markStart, markEnd } = await import('../perf');

      const start = markStart('noop:test');
      expect(start).toBe('');

      const measure = markEnd('noop:test', start);
      expect(measure).toBeNull();
    });
  });
});

/**
 * Threshold Checking Unit Tests
 *
 * Verifies that checkThresholds correctly identifies pass/fail conditions
 * based on p95 latency and error rate thresholds.
 */

import { describe, it, expect } from 'vitest';
import { checkThresholds, type ThresholdConfig } from './thresholds';
import type { OperationMetrics } from './metrics';

function makeMetrics(overrides: Partial<OperationMetrics> & { operation: string }): OperationMetrics {
  return {
    count: 100,
    errors: 0,
    latency: { p50: 500, p95: 1000, p99: 1500, max: 2000, min: 100, avg: 600 },
    throughputOpsPerSec: 10,
    ...overrides,
  };
}

describe('checkThresholds', () => {
  it('returns passed: true when all metrics are within limits', () => {
    const metrics: OperationMetrics[] = [
      makeMetrics({ operation: 'uploadFile', latency: { p50: 500, p95: 2000, p99: 3000, max: 4000, min: 100, avg: 600 } }),
      makeMetrics({ operation: 'createFolder', latency: { p50: 200, p95: 800, p99: 1200, max: 1500, min: 50, avg: 300 } }),
    ];

    const thresholds: ThresholdConfig[] = [
      { operation: 'uploadFile', p95MaxMs: 10_000, errorRateMax: 0.05 },
      { operation: 'createFolder', p95MaxMs: 5_000, errorRateMax: 0.10 },
    ];

    const result = checkThresholds(metrics, thresholds);
    expect(result.passed).toBe(true);
    expect(result.violations).toEqual([]);
  });

  it('returns passed: false when p95 exceeds threshold', () => {
    const metrics: OperationMetrics[] = [
      makeMetrics({
        operation: 'uploadFile',
        latency: { p50: 5000, p95: 12_000, p99: 15_000, max: 20_000, min: 1000, avg: 6000 },
      }),
    ];

    const thresholds: ThresholdConfig[] = [
      { operation: 'uploadFile', p95MaxMs: 10_000, errorRateMax: 0.05 },
    ];

    const result = checkThresholds(metrics, thresholds);
    expect(result.passed).toBe(false);
    expect(result.violations.length).toBeGreaterThan(0);
    expect(result.violations[0]).toContain('p95');
    expect(result.violations[0]).toContain('12000ms');
    expect(result.violations[0]).toContain('10000ms');
  });

  it('returns passed: false when error rate exceeds threshold', () => {
    const metrics: OperationMetrics[] = [
      makeMetrics({
        operation: 'uploadFile',
        count: 100,
        errors: 10, // 10% error rate
        latency: { p50: 500, p95: 2000, p99: 3000, max: 4000, min: 100, avg: 600 },
      }),
    ];

    const thresholds: ThresholdConfig[] = [
      { operation: 'uploadFile', p95MaxMs: 10_000, errorRateMax: 0.05 }, // 5% max
    ];

    const result = checkThresholds(metrics, thresholds);
    expect(result.passed).toBe(false);
    expect(result.violations.length).toBeGreaterThan(0);
    expect(result.violations[0]).toContain('error rate');
    expect(result.violations[0]).toContain('10.0%');
    expect(result.violations[0]).toContain('5.0%');
  });

  it('skips operations not found in metrics (no false violation)', () => {
    const metrics: OperationMetrics[] = [
      makeMetrics({ operation: 'uploadFile' }),
    ];

    const thresholds: ThresholdConfig[] = [
      { operation: 'uploadFile', p95MaxMs: 10_000, errorRateMax: 0.05 },
      { operation: 'createFolder', p95MaxMs: 5_000, errorRateMax: 0.10 }, // not in metrics
      { operation: 'deleteItem', p95MaxMs: 3_000, errorRateMax: 0.05 },   // not in metrics
    ];

    const result = checkThresholds(metrics, thresholds);
    expect(result.passed).toBe(true);
    expect(result.violations).toEqual([]);
  });

  it('violation message includes operation name, observed value, and threshold value', () => {
    const metrics: OperationMetrics[] = [
      makeMetrics({
        operation: 'createFolder',
        count: 50,
        errors: 10, // 20% error rate
        latency: { p50: 3000, p95: 6000, p99: 8000, max: 10000, min: 500, avg: 4000 },
      }),
    ];

    const thresholds: ThresholdConfig[] = [
      { operation: 'createFolder', p95MaxMs: 5_000, errorRateMax: 0.10 },
    ];

    const result = checkThresholds(metrics, thresholds);
    expect(result.passed).toBe(false);
    expect(result.violations).toHaveLength(2);

    // p95 violation
    const p95Violation = result.violations.find((v) => v.includes('p95'));
    expect(p95Violation).toBeDefined();
    expect(p95Violation).toContain('createFolder');
    expect(p95Violation).toContain('6000ms');
    expect(p95Violation).toContain('5000ms');

    // error rate violation
    const errorViolation = result.violations.find((v) => v.includes('error rate'));
    expect(errorViolation).toBeDefined();
    expect(errorViolation).toContain('createFolder');
    expect(errorViolation).toContain('20.0%');
    expect(errorViolation).toContain('10.0%');
  });
});

import { test, expect, Browser, BrowserContext, Page } from '@playwright/test';
import type { PrivateKeyAccount } from 'viem/accounts';
import {
  createTestAccount,
  setupMockWallet,
  loginViaWallet,
} from '../utils/wallet-login-helpers';
import {
  createWalletTestAccount,
  closeWalletTestAccounts,
  navigateToShared,
  navigateToFiles,
  type WalletTestAccount,
} from '../utils/multi-account-wallet';
import { createTestTextFile, cleanupTestFiles } from '../utils/test-files';
import { FileListPage } from '../page-objects/file-browser/file-list.page';
import { UploadZonePage } from '../page-objects/file-browser/upload-zone.page';
import { ContextMenuPage } from '../page-objects/file-browser/context-menu.page';
import { ShareDialogPage } from '../page-objects/dialogs/share-dialog.page';
import { SharedFileBrowserPage } from '../page-objects/file-browser/shared-file-browser.page';

/**
 * Journey Timing E2E Test Suite
 *
 * Measures real browser wall-clock time for three critical user journeys:
 * 1. Login-to-Vault: Mock wallet login -> file list visible
 * 2. Upload-to-Visible: File upload -> file appears in list
 * 3. Share-to-Accessible: Share creation -> recipient sees shared item
 *
 * All timings use performance.now() (high resolution, ~microsecond precision).
 * Results are output as structured JSON prefixed with JOURNEY_TIMING: for grep capture.
 *
 * PERF-06: End-to-end user journey timing baselines.
 */

interface JourneyResult {
  journey: string;
  totalMs: number | null;
  phases?: Record<string, number>;
  fileSizeBytes?: number;
  note?: string;
  partial?: Record<string, number>;
}

const journeyResults: JourneyResult[] = [];

test.describe.serial('Journey Timing', () => {
  // Shared state across serial tests
  let browser: Browser;
  let context: BrowserContext;
  let page: Page;
  let account: PrivateKeyAccount;

  // Page objects for Alice (primary account)
  let fileList: FileListPage;
  let uploadZone: UploadZonePage;

  // For share journey
  let bob: WalletTestAccount | null = null;

  // Test data
  const runId = Date.now().toString();
  const uploadFileName = `journey-upload-${runId}.txt`;
  const shareFileName = `journey-share-${runId}.txt`;

  test.beforeAll(async ({ browser: testBrowser }) => {
    browser = testBrowser;
  });

  test.afterAll(async () => {
    cleanupTestFiles();

    // Output summary of all journey results
    console.log(
      `JOURNEY_TIMING: ${JSON.stringify({
        summary: true,
        capturedAt: new Date().toISOString(),
        journeys: journeyResults,
      })}`
    );

    // Close Bob's context if created
    if (bob) {
      await closeWalletTestAccounts([bob]);
    }

    // Close Alice's context
    if (context) {
      await context.close();
    }
  });

  // ============================================
  // Journey 1: Login-to-Vault
  // ============================================

  test('Journey 1: login-to-vault', async () => {
    test.setTimeout(120_000);

    // Setup: create account and context BEFORE timing starts
    account = createTestAccount();
    context = await browser.newContext();
    page = await context.newPage();
    await setupMockWallet(page, account);

    // --- TIMING START ---
    const journeyStart = performance.now();

    // Navigate to login page and initiate wallet login
    await page.goto('/');

    // Wait for Core Kit to initialize (wallet button becomes enabled)
    const walletButton = page.locator('[data-testid="wallet-login-button"]');
    await walletButton.waitFor({ state: 'visible', timeout: 20_000 });
    await page.waitForFunction(
      () => {
        const btn = document.querySelector(
          '[data-testid="wallet-login-button"]'
        ) as HTMLButtonElement;
        return btn && !btn.disabled;
      },
      { timeout: 20_000 }
    );

    // Click wallet button and select Mock Wallet
    await walletButton.click();
    const connectorList = page.locator('.wallet-connector-list');
    await connectorList.waitFor({ state: 'visible', timeout: 5_000 });
    const mockWalletOption = page.locator('.wallet-connector-option', {
      hasText: 'Mock Wallet',
    });
    await mockWalletOption.click();

    // Wait for redirect to /files
    await page.waitForURL('**/files', { timeout: 60_000 });
    const walletAuthEnd = performance.now();

    // Wait for file list or empty state to be visible (vault loaded)
    await Promise.race([
      page.locator('.file-list[role="grid"]').waitFor({ state: 'visible', timeout: 30_000 }),
      page.locator('[data-testid="empty-state"]').waitFor({ state: 'visible', timeout: 30_000 }),
    ]);

    // --- TIMING END ---
    const journeyEnd = performance.now();

    const walletAuthMs = Math.round(walletAuthEnd - journeyStart);
    const vaultLoadMs = Math.round(journeyEnd - walletAuthEnd);
    const totalMs = Math.round(journeyEnd - journeyStart);

    const result: JourneyResult = {
      journey: 'login-to-vault',
      totalMs,
      phases: { walletAuthMs, vaultLoadMs },
    };

    journeyResults.push(result);
    console.log(`JOURNEY_TIMING: ${JSON.stringify(result)}`);

    // Sanity check: should complete in under 60s
    expect(totalMs).toBeLessThan(60_000);

    // Initialize page objects for subsequent tests
    fileList = new FileListPage(page);
    uploadZone = new UploadZonePage(page);
  });

  // ============================================
  // Journey 2: Upload-to-Visible
  // ============================================

  test('Journey 2: upload-to-visible', async () => {
    test.setTimeout(60_000);

    // Create a 100KB test file
    const fileContent = 'x'.repeat(102_400); // 100KB of text
    const testFile = createTestTextFile(uploadFileName, fileContent);

    // --- TIMING START ---
    const journeyStart = performance.now();

    // Upload via file input
    await uploadZone.uploadFile(testFile.path);

    // Wait for file to appear in the file list
    await fileList.waitForItemToAppear(uploadFileName, { timeout: 30_000 });

    // --- TIMING END ---
    const journeyEnd = performance.now();

    const totalMs = Math.round(journeyEnd - journeyStart);

    const result: JourneyResult = {
      journey: 'upload-to-visible',
      totalMs,
      fileSizeBytes: 102_400,
    };

    journeyResults.push(result);
    console.log(`JOURNEY_TIMING: ${JSON.stringify(result)}`);

    // Sanity check: should complete in under 30s
    expect(totalMs).toBeLessThan(30_000);
  });

  // ============================================
  // Journey 3: Share-to-Accessible
  // ============================================

  test('Journey 3: share-to-accessible', async () => {
    test.setTimeout(180_000);

    // Alice needs a file to share. Upload a dedicated file for this journey.
    const shareContent = 'This file is for the share timing journey';
    const shareFile = createTestTextFile(shareFileName, shareContent);
    await uploadZone.uploadFile(shareFile.path);
    await fileList.waitForItemToAppear(shareFileName, { timeout: 30_000 });

    // Create Bob's account (separate context, separate wallet identity)
    try {
      bob = await createWalletTestAccount(browser, 'bob');
    } catch (err) {
      // If Bob's account creation fails, record a partial result
      const result: JourneyResult = {
        journey: 'share-to-accessible',
        totalMs: null,
        note: `Multi-account setup failed: ${err instanceof Error ? err.message : String(err)}`,
      };
      journeyResults.push(result);
      console.log(`JOURNEY_TIMING: ${JSON.stringify(result)}`);
      return;
    }

    // Initialize page objects
    const aliceContextMenu = new ContextMenuPage(page);
    const aliceShareDialog = new ShareDialogPage(page);
    const bobSharedBrowser = new SharedFileBrowserPage(bob.page);

    // --- TIMING START ---
    const journeyStart = performance.now();

    // Alice: right-click file -> Share -> enter Bob's public key -> confirm
    await fileList.rightClickItem(shareFileName);
    await aliceContextMenu.waitForOpen();
    await aliceContextMenu.clickShare();
    await aliceShareDialog.waitForOpen();
    await aliceShareDialog.waitForRecipientsLoaded();
    await aliceShareDialog.shareWithKey(bob.publicKey);
    await aliceShareDialog.waitForSuccess({ timeout: 30_000 });
    await aliceShareDialog.close();

    const shareCreateEnd = performance.now();

    // Bob: navigate to Shared section and wait for the shared item
    await navigateToShared(bob);
    await bobSharedBrowser.waitForLoaded({ timeout: 30_000 });
    await bobSharedBrowser.waitForSharedItem(shareFileName, { timeout: 30_000 });

    // --- TIMING END ---
    const journeyEnd = performance.now();

    const shareCreateMs = Math.round(shareCreateEnd - journeyStart);
    const recipientAccessMs = Math.round(journeyEnd - shareCreateEnd);
    const totalMs = Math.round(journeyEnd - journeyStart);

    const result: JourneyResult = {
      journey: 'share-to-accessible',
      totalMs,
      phases: { shareCreateMs, recipientAccessMs },
    };

    journeyResults.push(result);
    console.log(`JOURNEY_TIMING: ${JSON.stringify(result)}`);

    // Sanity check: should complete in under 120s
    expect(totalMs).toBeLessThan(120_000);
  });
});

/**
 * Load Test Threshold Checking
 *
 * Defines pass/fail thresholds for load test scenarios.
 * Compares observed metrics against defined limits and produces
 * actionable violation messages for CI output.
 */

import type { OperationMetrics } from './metrics';

export interface ThresholdConfig {
  /** Operation name to match against OperationMetrics.operation */
  operation: string;
  /** Maximum allowed p95 latency in milliseconds */
  p95MaxMs: number;
  /** Maximum allowed error rate (0.0 to 1.0) */
  errorRateMax: number;
}

export interface ThresholdResult {
  passed: boolean;
  violations: string[];
}

/**
 * Check collected metrics against defined thresholds.
 * Returns pass/fail with descriptive violation messages.
 *
 * Operations in thresholds that are not found in metrics are silently
 * skipped — a scenario may not exercise every operation.
 */
export function checkThresholds(
  metrics: OperationMetrics[],
  thresholds: ThresholdConfig[]
): ThresholdResult {
  const violations: string[] = [];

  for (const t of thresholds) {
    const m = metrics.find((op) => op.operation === t.operation);
    if (!m) continue;

    if (m.latency.p95 > t.p95MaxMs) {
      violations.push(
        `${t.operation} p95 ${Math.round(m.latency.p95)}ms exceeds threshold ${t.p95MaxMs}ms`
      );
    }

    const errorRate = m.count > 0 ? m.errors / m.count : 0;
    if (errorRate > t.errorRateMax) {
      violations.push(
        `${t.operation} error rate ${(errorRate * 100).toFixed(1)}% exceeds threshold ${(t.errorRateMax * 100).toFixed(1)}%`
      );
    }
  }

  return { passed: violations.length === 0, violations };
}

