  1→import axios, { type AxiosProgressEvent, type CancelToken } from 'axios';
  2→import type {
  3→  SdkContext,
  4→  IpfsAddResult,
  5→  ProgressCallback,
  6→  DownloadProgressCallback,
  7→} from '../types';
  8→
  9→/**
 10→ * Upload encrypted data to IPFS via backend relay.
 11→ * Uses ctx.axiosInstance when available (gets auth interceptors + default headers),
 12→ * falls back to bare axios with manual token injection.
 13→ */
 14→export async function addToIpfs(
 15→  ctx: SdkContext,
 16→  encryptedData: Uint8Array,
 17→  onProgress?: ProgressCallback,
 18→  cancelToken?: CancelToken
 19→): Promise<IpfsAddResult> {
 20→  const blob = new Blob([encryptedData as BlobPart]);
 21→  const formData = new FormData();
 22→  formData.append('file', blob);
 23→
 24→  const requestConfig = {
 25→    onUploadProgress: (event: AxiosProgressEvent) => {
 26→      if (event.total && onProgress) {
 27→        onProgress(Math.round((event.loaded * 100) / event.total));
 28→      }
 29→    },
 30→    cancelToken,
 31→  };
 32→
 33→  if (ctx.axiosInstance) {
 34→    const response = await ctx.axiosInstance.post<IpfsAddResult>(
 35→      '/ipfs/upload',
 36→      formData,
 37→      requestConfig
 38→    );
 39→    return response.data;
 40→  }
 41→
 42→  // Fallback: bare axios with manual token (no instance available)
 43→  const token = await ctx.getAccessToken();
 44→  const response = await axios.post<IpfsAddResult>(`${ctx.apiUrl}/ipfs/upload`, formData, {
 45→    headers: { Authorization: `Bearer ${token}` },
 46→    ...requestConfig,
 47→  });
 48→  return response.data;
 49→}
 50→
 51→/**
 52→ * Unpin file from IPFS via backend relay.
 53→ */
 54→export async function unpinFromIpfs(ctx: SdkContext, cid: string): Promise<void> {
 55→  if (ctx.axiosInstance) {
 56→    await ctx.axiosInstance.post('/ipfs/unpin', { cid });
 57→    return;
 58→  }
 59→
 60→  const token = await ctx.getAccessToken();
 61→  await axios.post(
 62→    `${ctx.apiUrl}/ipfs/unpin`,
 63→    { cid },
 64→    { headers: { Authorization: `Bearer ${token}` } }
 65→  );
 66→}
 67→
 68→/**
 69→ * Fetch encrypted data from IPFS via backend relay.
 70→ * Uses native fetch for streaming download progress support.
 71→ * Auth token is obtained from ctx (axiosInstance interceptor isn't used
 72→ * here because fetch provides ReadableStream for progress tracking).
 73→ */
 74→export async function fetchFromIpfs(
 75→  ctx: SdkContext,
 76→  cid: string,
 77→  onProgress?: DownloadProgressCallback
 78→): Promise<Uint8Array> {
 79→  const token = await ctx.getAccessToken();
 80→  const response = await fetch(`${ctx.apiUrl}/ipfs/${cid}`, {
 81→    headers: { Authorization: `Bearer ${token}` },
 82→  });
 83→  if (!response.ok) throw new Error(`Failed to fetch from IPFS: ${response.status}`);
 84→
 85→  const contentLength = response.headers.get('Content-Length');
 86→  if (!onProgress || !contentLength) {
 87→    return new Uint8Array(await response.arrayBuffer());
 88→  }
 89→
 90→  const total = parseInt(contentLength, 10);
 91→  const reader = response.body?.getReader();
 92→  if (!reader) throw new Error('ReadableStream not supported');
 93→
 94→  const chunks: Uint8Array[] = [];
 95→  let loaded = 0;
 96→  while (true) {
 97→    const { done, value } = await reader.read();
 98→    if (done) break;
 99→    chunks.push(value);
100→    loaded += value.length;
101→    onProgress(loaded, total);
102→  }
103→
104→  const result = new Uint8Array(loaded);
105→  let offset = 0;
106→  for (const chunk of chunks) {
107→    result.set(chunk, offset);
108→    offset += chunk.length;
109→  }
110→  return result;
111→}
