  1→/**
  2→ * IPNS Service - Record creation, publishing, and resolution
  3→ *
  4→ * Extracted from: apps/web/src/services/ipns.service.ts
  5→ * Change: Uses @cipherbox/api-client generated functions instead of web app local imports.
  6→ * The ipns.service.ts was already clean (no store deps), so the extraction is straightforward.
  7→ */
  8→
  9→import { createIpnsRecord, marshalIpnsRecord, IPNS_SIGNATURE_PREFIX } from '@cipherbox/core';
 10→import { verifyEd25519, concatBytes } from '@cipherbox/crypto';
 11→import {
 12→  ipnsControllerPublishRecord,
 13→  ipnsControllerPublishBatch,
 14→  ipnsControllerResolveRecord,
 15→} from '@cipherbox/api-client';
 16→import type { PublishIpnsEntryDtoRecordType } from '@cipherbox/api-client';
 17→import type { SdkContext } from '../types';
 18→
 19→/**
 20→ * Create an IPNS record locally and publish via backend.
 21→ *
 22→ * The record is signed locally using the Ed25519 private key, then
 23→ * the backend relays it to the IPFS network via delegated routing.
 24→ *
 25→ * @param params.ipnsPrivateKey - Ed25519 private key (64 bytes in libp2p format)
 26→ * @param params.ipnsName - IPNS name (k51.../bafzaa... format)
 27→ * @param params.metadataCid - CID of the encrypted metadata blob
 28→ * @param params.sequenceNumber - Current sequence number (will be incremented before publish)
 29→ * @param params.encryptedIpnsPrivateKey - Hex ECIES-wrapped key for TEE (first publish only)
 30→ * @param params.keyEpoch - TEE key epoch (required with encryptedIpnsPrivateKey)
 31→ * @param params.expectedSequenceNumber - Pre-increment sequence number for conflict detection (folder records only)
 32→ */
 33→export async function createAndPublishIpnsRecord(params: {
 34→  ipnsPrivateKey: Uint8Array;
 35→  ipnsName: string;
 36→  metadataCid: string;
 37→  sequenceNumber: bigint;
 38→  encryptedIpnsPrivateKey?: string;
 39→  keyEpoch?: number;
 40→  expectedSequenceNumber?: string;
 41→  ctx?: SdkContext;
 42→}): Promise<{ success: boolean; sequenceNumber: bigint }> {
 43→  // 1. Create IPNS record pointing to /ipfs/{metadataCid}
 44→  // 24 hour lifetime (will be republished by TEE every 3 hours)
 45→  const record = await createIpnsRecord(
 46→    params.ipnsPrivateKey,
 47→    `/ipfs/${params.metadataCid}`,
 48→    params.sequenceNumber,
 49→    24 * 60 * 60 * 1000 // 24 hours in ms
 50→  );
 51→
 52→  // 2. Marshal to bytes for transport
 53→  const recordBytes = marshalIpnsRecord(record);
 54→
 55→  // 3. Base64 encode for API transmission (loop-based to avoid call stack overflow on large records)
 56→  let binary = '';
 57→  for (let i = 0; i < recordBytes.length; i++) {
 58→    binary += String.fromCharCode(recordBytes[i]);
 59→  }
 60→  const recordBase64 = btoa(binary);
 61→
 62→  // 4. Call backend API to relay to IPFS network
 63→  const apiOptions = params.ctx?.axiosInstance
 64→    ? { _axiosInstance: params.ctx.axiosInstance }
 65→    : undefined;
 66→  const response = await ipnsControllerPublishRecord(
 67→    {
 68→      ipnsName: params.ipnsName,
 69→      record: recordBase64,
 70→      metadataCid: params.metadataCid,
 71→      encryptedIpnsPrivateKey: params.encryptedIpnsPrivateKey,
 72→      keyEpoch: params.keyEpoch,
 73→      expectedSequenceNumber: params.expectedSequenceNumber,
 74→    },
 75→    apiOptions
 76→  );
 77→
 78→  return {
 79→    success: response.success,
 80→    sequenceNumber: BigInt(response.sequenceNumber),
 81→  };
 82→}
 83→
 84→/**
 85→ * Batch publish multiple IPNS records in a single API call.
 86→ *
 87→ * Sends all records (folder and/or file) to the batch endpoint,
 88→ * which processes them with concurrency-limited parallelism.
 89→ * Partial success is allowed: individual failures do not fail the batch.
 90→ *
 91→ * @param records - Array of IPNS record payloads to publish
 92→ * @returns Success and failure counts
 93→ */
 94→export async function batchPublishIpnsRecords(
 95→  records: Array<{
 96→    ipnsName: string;
 97→    recordBase64: string;
 98→    metadataCid: string;
 99→    encryptedIpnsPrivateKey?: string;
100→    keyEpoch?: number;
101→    recordType?: 'folder' | 'file';
102→    /** Pre-increment sequence number for conflict detection (folder records only) */
103→    expectedSequenceNumber?: string;
104→  }>,
105→  ctx?: SdkContext
106→): Promise<{ totalSucceeded: number; totalFailed: number }> {
107→  const apiOptions = ctx?.axiosInstance ? { _axiosInstance: ctx.axiosInstance } : undefined;
108→  const response = await ipnsControllerPublishBatch(
109→    {
110→      records: records.map((r) => ({
111→        ipnsName: r.ipnsName,
112→        record: r.recordBase64,
113→        metadataCid: r.metadataCid,
114→        encryptedIpnsPrivateKey: r.encryptedIpnsPrivateKey,
115→        keyEpoch: r.keyEpoch,
116→        recordType: r.recordType as PublishIpnsEntryDtoRecordType | undefined,
117→        expectedSequenceNumber: r.expectedSequenceNumber,
118→      })),
119→    },
120→    apiOptions
121→  );
122→
123→  return {
124→    totalSucceeded: response.totalSucceeded,
125→    totalFailed: response.totalFailed,
126→  };
127→}
128→
129→/**
130→ * Verify the Ed25519 signature on an IPNS record.
131→ * Per IPFS spec, the signature is over "ipns-signature:" + cborData.
132→ *
133→ * @param signatureV2 - base64 Ed25519 signature (64 bytes)
134→ * @param data - base64 CBOR data that was signed
135→ * @param pubKey - base64 raw Ed25519 public key (32 bytes)
136→ * @returns true if valid
137→ */
138→export async function verifyIpnsSignature(
139→  signatureV2: string,
140→  data: string,
141→  pubKey: string
142→): Promise<boolean> {
143→  const sigBytes = Uint8Array.from(atob(signatureV2), (c) => c.charCodeAt(0));
144→  const dataBytes = Uint8Array.from(atob(data), (c) => c.charCodeAt(0));
145→  const pubKeyBytes = Uint8Array.from(atob(pubKey), (c) => c.charCodeAt(0));
146→
147→  // Per IPFS IPNS spec, signature is over "ipns-signature:" + cborData
148→  const signedData = concatBytes(IPNS_SIGNATURE_PREFIX, dataBytes);
149→  return verifyEd25519(sigBytes, signedData, pubKeyBytes);
150→}
151→
152→/**
153→ * Resolve an IPNS name to its current CID and sequence number.
154→ *
155→ * Calls backend API which relays to the delegated routing service for resolution.
156→ * When the response includes IPNS signature data (from delegated routing),
157→ * verifies the Ed25519 signature before trusting the CID.
158→ *
159→ * @param ipnsName - IPNS name to resolve (k51.../bafzaa... format)
160→ * @returns Current CID, sequence number, and signature verification status, or null if not found
161→ */
162→export async function resolveIpnsRecord(
163→  ipnsName: string,
164→  ctx?: SdkContext
165→): Promise<{ cid: string; sequenceNumber: bigint; signatureVerified: boolean } | null> {
166→  try {
167→    const apiOptions = ctx?.axiosInstance ? { _axiosInstance: ctx.axiosInstance } : undefined;
168→    const response = await ipnsControllerResolveRecord({ ipnsName }, apiOptions);
169→
170→    if (!response.success) {
171→      return null;
172→    }
173→
174→    // Verify IPNS signature if all signature fields are present
175→    let signatureVerified = false;
176→    if (response.signatureV2 && response.data && response.pubKey) {
177→      const valid = await verifyIpnsSignature(response.signatureV2, response.data, response.pubKey);
178→      if (!valid) {
179→        throw new Error('IPNS signature verification failed - record may be tampered');
180→      }
181→      signatureVerified = true;
182→    } else {
183→      console.warn('IPNS resolve returned without signature data, skipping verification');
184→    }
185→
186→    return {
187→      cid: response.cid,
188→      sequenceNumber: BigInt(response.sequenceNumber),
189→      signatureVerified,
190→    };
191→  } catch (error) {
192→    // 404 means IPNS name not found - return null
193→    // Other errors should propagate (including signature verification failures)
194→    if (error instanceof Error && (error as Error & { status?: number }).status === 404) {
195→      return null;
196→    }
197→    throw error;
198→  }
199→}
