  1→/**
  2→ * Folder operations - Stateless folder CRUD with encryption
  3→ *
  4→ * Extracted from: apps/web/src/services/folder.service.ts
  5→ * All store access replaced with explicit parameters.
  6→ * Functions take metadata in, return updated metadata out.
  7→ */
  8→
  9→import {
 10→  generateEd25519Keypair,
 11→  deriveIpnsName,
 12→  generateRandomBytes,
 13→  wrapKey,
 14→  bytesToHex,
 15→  hexToBytes,
 16→} from '@cipherbox/crypto';
 17→import {
 18→  encryptFolderMetadata,
 19→  decryptFolderMetadata,
 20→  type FolderMetadata,
 21→  type EncryptedFolderMetadata,
 22→  type FolderEntry,
 23→  type FolderChild,
 24→  type FilePointer,
 25→} from '@cipherbox/core';
 26→import type { SdkContext, TeeKeys } from '../types';
 27→import { addToIpfs, fetchFromIpfs } from '../ipfs';
 28→import { createAndPublishIpnsRecord, resolveIpnsRecord } from '../ipns';
 29→
 30→/**
 31→ * Fetch and decrypt folder metadata from IPFS.
 32→ *
 33→ * @param cid - IPFS CID of the encrypted metadata blob
 34→ * @param folderKey - Decrypted AES-256 folder key
 35→ * @param ctx - SDK context for IPFS access
 36→ * @returns Decrypted folder metadata (v2)
 37→ */
 38→export async function fetchAndDecryptMetadata(
 39→  cid: string,
 40→  folderKey: Uint8Array,
 41→  ctx: SdkContext
 42→): Promise<FolderMetadata> {
 43→  const encryptedBytes = await fetchFromIpfs(ctx, cid);
 44→
 45→  // All folder metadata (including root) is v1 JSON {iv, data}.
 46→  // v2 blob format is only for the vault key blob (separate IPNS name).
 47→  const encryptedJson = new TextDecoder().decode(encryptedBytes);
 48→  const encrypted: EncryptedFolderMetadata = JSON.parse(encryptedJson);
 49→  return decryptFolderMetadata(encrypted, folderKey);
 50→}
 51→
 52→/**
 53→ * Load a folder's metadata from IPNS.
 54→ *
 55→ * Resolves the folder's IPNS name to get the current metadata CID,
 56→ * fetches and decrypts the metadata.
 57→ *
 58→ * @returns Decrypted folder metadata, sequence number, and CID, or null if IPNS not found
 59→ */
 60→export async function loadFolderMetadata(params: {
 61→  ipnsName: string;
 62→  folderKey: Uint8Array;
 63→  ctx: SdkContext;
 64→}): Promise<{
 65→  metadata: FolderMetadata;
 66→  sequenceNumber: bigint;
 67→  cid: string;
 68→} | null> {
 69→  const resolved = await resolveIpnsRecord(params.ipnsName, params.ctx);
 70→  if (!resolved) return null;
 71→
 72→  const metadata = await fetchAndDecryptMetadata(resolved.cid, params.folderKey, params.ctx);
 73→
 74→  return {
 75→    metadata,
 76→    sequenceNumber: resolved.sequenceNumber,
 77→    cid: resolved.cid,
 78→  };
 79→}
 80→
 81→/**
 82→ * Create a new subfolder with generated keys.
 83→ *
 84→ * Generates new Ed25519 IPNS keypair and AES-256 folder key,
 85→ * wraps them with the user's public key for storage.
 86→ *
 87→ * @returns Created folder entry and decrypted keys
 88→ */
 89→export async function createSubfolder(params: {
 90→  name: string;
 91→  userPublicKey: Uint8Array;
 92→  teeKeys?: TeeKeys;
 93→}): Promise<{
 94→  folder: FolderEntry;
 95→  ipnsPrivateKey: Uint8Array;
 96→  folderKey: Uint8Array;
 97→  encryptedIpnsPrivateKey?: string;
 98→  keyEpoch?: number;
 99→}> {
100→  // 1. Generate Ed25519 keypair for folder IPNS
101→  const ipnsKeypair = await generateEd25519Keypair();
102→  const ipnsName = await deriveIpnsName(ipnsKeypair.publicKey);
103→
104→  // 2. Generate random AES-256 folder key
105→  const folderKey = generateRandomBytes(32);
106→
107→  // 3. Wrap keys with user's public key (ECIES encryption)
108→  const ipnsPrivateKeyEncrypted = bytesToHex(
109→    await wrapKey(ipnsKeypair.privateKey, params.userPublicKey)
110→  );
111→  const folderKeyEncrypted = bytesToHex(await wrapKey(folderKey, params.userPublicKey));
112→
113→  // 4. TEE-02: Encrypt IPNS private key with TEE public key for republishing.
114→  //    Wrap remaining steps in try/catch to zero key material on error.
115→  //    On success the caller receives the keys, so we only zero on failure.
116→  try {
117→    let encryptedIpnsPrivateKey: string | undefined;
118→    let keyEpoch: number | undefined;
119→
120→    if (params.teeKeys?.currentPublicKey) {
121→      const teePublicKey = hexToBytes(params.teeKeys.currentPublicKey);
122→      const encryptedKey = await wrapKey(ipnsKeypair.privateKey, teePublicKey);
123→      encryptedIpnsPrivateKey = bytesToHex(encryptedKey);
124→      keyEpoch = params.teeKeys.currentEpoch;
125→    }
126→
127→    // 5. Create folder entry for parent's metadata
128→    const now = Date.now();
129→    const folder: FolderEntry = {
130→      type: 'folder',
131→      id: crypto.randomUUID(),
132→      name: params.name,
133→      ipnsName,
134→      ipnsPrivateKeyEncrypted,
135→      folderKeyEncrypted,
136→      createdAt: now,
137→      modifiedAt: now,
138→    };
139→
140→    return {
141→      folder,
142→      ipnsPrivateKey: ipnsKeypair.privateKey,
143→      folderKey,
144→      encryptedIpnsPrivateKey,
145→      keyEpoch,
146→    };
147→  } catch (error) {
148→    ipnsKeypair.privateKey.fill(0);
149→    folderKey.fill(0);
150→    throw error;
151→  }
152→}
153→
154→/**
155→ * Update folder metadata and publish to IPNS.
156→ *
157→ * Encrypts the metadata with the folder key, uploads to IPFS,
158→ * and publishes an updated IPNS record pointing to the new CID.
159→ *
160→ * @returns New CID and sequence number
161→ */
162→export async function updateFolderMetadataAndPublish(params: {
163→  children: FolderChild[];
164→  folderKey: Uint8Array;
165→  ipnsPrivateKey: Uint8Array;
166→  ipnsName: string;
167→  sequenceNumber: bigint;
168→  ctx: SdkContext;
169→  encryptedIpnsPrivateKey?: string;
170→  keyEpoch?: number;
171→}): Promise<{ cid: string; newSequenceNumber: bigint }> {
172→  // 1. Create v2 folder metadata
173→  const metadata: FolderMetadata = {
174→    version: 'v2',
175→    children: params.children,
176→  };
177→
178→  // 2. Encrypt metadata with folder key
179→  const encrypted = await encryptFolderMetadata(metadata, params.folderKey);
180→
181→  // 3. Upload to IPFS via backend relay
182→  const jsonStr = JSON.stringify(encrypted);
183→  const encryptedBytes = new TextEncoder().encode(jsonStr);
184→  const { cid } = await addToIpfs(params.ctx, encryptedBytes);
185→
186→  // 4. Publish IPNS record with conflict retry
187→  //    On 409, resolve current seq from IPNS and retry once
188→  let currentSeq = params.sequenceNumber;
189→
190→  for (let attempt = 0; attempt < 2; attempt++) {
191→    const newSeq = currentSeq + 1n;
192→    try {
193→      await createAndPublishIpnsRecord({
194→        ipnsPrivateKey: params.ipnsPrivateKey,
195→        ipnsName: params.ipnsName,
196→        metadataCid: cid,
197→        sequenceNumber: newSeq,
198→        encryptedIpnsPrivateKey: params.encryptedIpnsPrivateKey,
199→        keyEpoch: params.keyEpoch,
200→        expectedSequenceNumber: currentSeq.toString(),
201→        ctx: params.ctx,
202→      });
203→      return { cid, newSequenceNumber: newSeq };
204→    } catch (err) {
205→      const is409 =
206→        (err as Error & { status?: number }).status === 409 ||
207→        (err as Error & { response?: { status?: number } }).response?.status === 409;
208→      if (!is409 || attempt > 0) throw err;
209→
210→      // Re-sync: resolve current seq from IPNS
211→      const resolved = await resolveIpnsRecord(params.ipnsName, params.ctx);
212→      if (resolved) {
213→        currentSeq = resolved.sequenceNumber;
214→      } else {
215→        throw err; // Can't resolve → give up
216→      }
217→    }
218→  }
219→
220→  // Should not reach here, but TypeScript needs it
221→  throw new Error('Publish failed after retry');
222→}
223→
224→/**
225→ * Rename a child entry (folder or file) in folder metadata.
226→ *
227→ * Pure metadata operation: returns updated children array without publishing.
228→ */
229→export function renameInFolder(params: {
230→  children: FolderChild[];
231→  childId: string;
232→  newName: string;
233→}): { updatedChildren: FolderChild[]; renamedChild: FolderChild } {
234→  const children = [...params.children];
235→  const index = children.findIndex((c) => c.id === params.childId);
236→
237→  if (index === -1) throw new Error('Item not found');
238→
239→  const nameExists = children.some((c) => c.name === params.newName && c.id !== params.childId);
240→  if (nameExists) throw new Error('An item with this name already exists');
241→
242→  const renamedChild = {
243→    ...children[index],
244→    name: params.newName,
245→    modifiedAt: Date.now(),
246→  };
247→  children[index] = renamedChild;
248→
249→  return { updatedChildren: children, renamedChild };
250→}
251→
252→/**
253→ * Remove a child entry (folder or file) from folder metadata.
254→ *
255→ * Pure metadata operation: returns updated children array and the removed item.
256→ */
257→export function deleteFromFolder(params: { children: FolderChild[]; childId: string }): {
258→  updatedChildren: FolderChild[];
259→  removedItem: FolderChild;
260→} {
261→  const index = params.children.findIndex((c) => c.id === params.childId);
262→  if (index === -1) throw new Error('Item not found');
263→
264→  const removedItem = params.children[index];
265→  const updatedChildren = params.children.filter((c) => c.id !== params.childId);
266→
267→  return { updatedChildren, removedItem };
268→}
269→
270→/**
271→ * Add a file pointer to folder children.
272→ *
273→ * Pure metadata operation: returns updated children array with the new file pointer.
274→ */
275→export function addFilePointerToFolder(params: {
276→  children: FolderChild[];
277→  fileId: string;
278→  fileName: string;
279→  fileMetaIpnsName: string;
280→  ipnsPrivateKeyEncrypted: string;
281→}): { updatedChildren: FolderChild[]; filePointer: FilePointer } {
282→  const nameExists = params.children.some((c) => c.name === params.fileName);
283→  if (nameExists) throw new Error('A file with this name already exists');
284→
285→  const now = Date.now();
286→  const filePointer: FilePointer = {
287→    type: 'file',
288→    id: params.fileId,
289→    name: params.fileName,
290→    fileMetaIpnsName: params.fileMetaIpnsName,
291→    ipnsPrivateKeyEncrypted: params.ipnsPrivateKeyEncrypted,
292→    createdAt: now,
293→    modifiedAt: now,
294→  };
295→
296→  return {
297→    updatedChildren: [...params.children, filePointer],
298→    filePointer,
299→  };
300→}
301→
302→/**
303→ * Move a child entry between folders.
304→ *
305→ * Pure metadata operation: returns updated source and dest children arrays.
306→ * Uses add-before-remove pattern conceptually (caller publishes dest first, then source).
307→ */
308→export function moveItem(params: {
309→  sourceChildren: FolderChild[];
310→  destChildren: FolderChild[];
311→  childId: string;
312→}): {
313→  updatedSourceChildren: FolderChild[];
314→  updatedDestChildren: FolderChild[];
315→  movedItem: FolderChild;
316→} {
317→  const index = params.sourceChildren.findIndex((c) => c.id === params.childId);
318→  if (index === -1) throw new Error('Item not found');
319→
320→  const movedItem = {
321→    ...params.sourceChildren[index],
322→    modifiedAt: Date.now(),
323→  };
324→
325→  // Check name collision in destination
326→  const nameExists = params.destChildren.some((c) => c.name === movedItem.name);
327→  if (nameExists) {
328→    throw new Error('An item with this name already exists in destination');
329→  }
330→
331→  const updatedSourceChildren = params.sourceChildren.filter((c) => c.id !== params.childId);
332→  const updatedDestChildren = [...params.destChildren, movedItem];
333→
334→  return { updatedSourceChildren, updatedDestChildren, movedItem };
335→}
